const data = $input.first().json.telefono || $input.first().json.telefono ;

// Aseguramos que sea texto
const telefono = data.toString().replace(/\D/g, ''); // quitamos espacios y símbolos

// Quitamos prefijos 54 y 9 (Argentina + móvil)
let sinPrefijo = telefono.replace(/^54/, '').replace(/^9/, '');

// Ahora detectamos el código de área.
// En Argentina los códigos de área van de 2 a 4 dígitos (por ejemplo: 11, 223, 2283, etc.)
let code = '';
if (sinPrefijo.startsWith('11')) {
  code = '11';
} else {
  // tomamos los primeros 3 o 4 dígitos según el patrón más común
  code = sinPrefijo.substring(0, 4);
}

return {
  json: {
    code: code
  }
};

