const trigger = $('When Executed by Another Workflow').first().json || {};

function limpiar(valor) {
  return valor !== undefined && valor !== null
    ? valor.toString().trim()
    : "";
}

function normalizarProducto(producto = "") {
  const p = limpiar(producto).toLowerCase();

  // MG Cyberster
  if (p.includes("cyberster")) {
    return {
      nombre: "MG Cyberster",
      id: 118
    };
  }

  // MG ZS Hybrid+
  if (p.includes("zs")) {
    return {
      nombre: "MG ZS Hybrid+",
      id: 117
    };
  }

  // MG 3 Hybrid+
  if (
    p.includes("mg 3") ||
    p.includes("3 hybrid") ||
    p === "3"
  ) {
    return {
      nombre: "MG 3 Hybrid+",
      id: 116
    };
  }

  // Default
  return {
    nombre: limpiar(producto),
    id: ""
  };
}

// El Execute Workflow Trigger recibe los datos directamente en trigger
const productoData = normalizarProducto(
  trigger.modelo || trigger.producto
);

return [
  {
    json: {
      idConversation: limpiar(trigger.idConversation),
      fecha: limpiar(trigger.fecha),
      hora: limpiar(trigger.hora),

      nombre: limpiar(trigger.nombre),
      telefono: limpiar(trigger.telefono),

      producto: productoData.nombre,
      product_of_interest_id: productoData.id,

      pago: limpiar(trigger.pago),
      usado: limpiar(trigger.usado),

      zona: limpiar(trigger.zona),

      dealer: limpiar(trigger.dealer),
      grupoCaptura: limpiar(trigger.grupoCaptura),
      tiene_grupo:
        trigger.tiene_grupo !== undefined
          ? trigger.tiene_grupo
          : false,

      interes: limpiar(trigger.interes)
    }
  }
];

