    origin_pilots_2: "FXG2THXIIAZBBD5OW"
  },
  "AUTOVISIONES": {
    origin_pilots: "3E9FA5DD-2971-4BFE-A6CC-C905D8F8C487",
    origin_pilots_2: "FXG2THXIIAZBBD5OW"
  }
};

// Función para validar valores
const esValido = (v) =>
  v !== undefined &&
  v !== null &&
  String(v).trim() !== "" &&
  String(v).trim() !== "-";

return items.map(item => {

  const query = item.json.query || {};

  // Buscar grupo captura en todos los lugares posibles
  let grupoCaptura =
    query["grupo captura"] ||
    query.grupoCaptura ||
    item.json["grupo captura"] ||
    item.json.grupoCaptura ||
    "";

  // Buscar dealer en todos los lugares posibles
  const dealer =
    query.dealer ||
    item.json.dealer ||
    "";

  let tiene_grupo = false;

