  item.json.tiene_grupo = tiene_grupo;

  // Asignar origins si corresponde
  if (originMap[grupoCaptura]) {
    item.json.origin_pilots = originMap[grupoCaptura].origin_pilots;
    item.json.origin_pilots_2 = originMap[grupoCaptura].origin_pilots_2;
